def capitalize_words(text):
    """
    Capitalizes the first letter of each word in the given string `text`.

    Parameters:
    text (str): The input string containing words separated by spaces.

    Returns:
    str: The modified string with the first letter of each word capitalized.
    """
    result = []
    capitalize_next = True

    for char in text:
        if char == ' ':
            result.append(char)
            capitalize_next = True
        else:
            if capitalize_next and 'a' <= char <= 'z':
                result.append(chr(ord(char) - (ord('a') - ord('A'))))
            else:
                result.append(char)
            capitalize_next = False

    return ''.join(result)
