from typing import Generic, TypeVar, List, Optional

T = TypeVar('T')

class Stack(Generic[T]):
    def __init__(self) -> None:
        """Initialize an empty stack."""
        self.items: List[T] = []

    def push(self, item: T) -> None:
        """Add an item to the top of the stack."""
        self.items.append(item)

    def pop(self) -> T:
        """Remove and return the item from the top of the stack. Raises IndexError if the stack is empty."""
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self.items.pop()

    def peek(self) -> T:
        """Return the item at the top of the stack without removing it. Raises IndexError if the stack is empty."""
        if self.is_empty():
            raise IndexError("peek from empty stack")
        return self.items[-1]

    def is_empty(self) -> bool:
        """Return True if the stack is empty, otherwise False."""
        return len(self.items) == 0

    def __len__(self) -> int:
        """Return the number of items in the stack."""
        return len(self.items)

    def __str__(self) -> str:
        """Return a string representation of the stack."""
        return str(self.items)

    def __bool__(self) -> bool:
        """Return True if the stack is not empty, otherwise False."""
        return not self.is_empty()

    def clear(self) -> None:
        """Remove all items from the stack."""
        self.items.clear()
