class CircularBuffer:
    def __init__(self, size):
        self.size = size
        self.buffer = [None] * size
        self.start = 0
        self.end = 0
        self.count = 0

    def append(self, item):
        if self.is_full():
            self.start = (self.start + 1) % self.size
        else:
            self.count += 1
        self.buffer[self.end] = item
        self.end = (self.end + 1) % self.size

    def is_full(self):
        return self.count == self.size

    def is_empty(self):
        return self.count == 0

    def get_buffer(self):
        return self.buffer.copy()

def circular_buffer_to_list(buffer):
    """
    Convert a CircularBuffer object to a list keeping the insertion order.

    :param buffer: CircularBuffer instance
    :return: list containing the items in the order they were added
    """
    if buffer.is_empty():
        return []

    _buffer = buffer.get_buffer()
    items = []
    start_index = buffer.start
    num_items = buffer.count

    for _ in range(num_items):
        items.append(_buffer[start_index])
        start_index = (start_index + 1) % buffer.size

    return items
```

