def escape_special_characters(input_string):
    """
    Replaces special characters in the input string with their respective escape sequences.

    Parameters:
    input_string (str): The string to be processed.

    Returns:
    str: The modified string with special characters escaped.
    """
    result = ""
    for char in input_string:
        if char == "'":
            result += "\\'"
        elif char == '"':
            result += '\\"'
        elif char == '\\':
            result += "\\\\"
        elif char == '\0':
            result += "\\0"
        else:
            result += char
    return result
