class Library:
    def __init__(self):
        self.books = {}
        self.total_books = 0
        self.available_books = 0

    def add_book(self, title, quantity=1):
        """
        Adds a specified number of copies of a book to the library.

        :param title: The title of the book to add.
        :param quantity: The number of copies to add.
        """
        if title in self.books:
            self.books[title]["total"] += quantity
            self.books[title]["available"] += quantity
        else:
            self.books[title] = {"total": quantity, "available": quantity}

        self.total_books += quantity
        self.available_books += quantity

    def remove_book(self, title, quantity=1):
        """
        Removes a specified number of copies of a book from the library.

        :param title: The title of the book to remove.
        :param quantity: The number of copies to remove.
        """
        if title in self.books:
            if self.books[title]["total"] >= quantity:
                self.books[title]["total"] -= quantity
                self.books[title]["available"] -= quantity

                self.total_books -= quantity
                self.available_books -= quantity

                if self.books[title]["total"] == 0:
                    del self.books[title]
            else:
                print(f"Not enough copies of {title} to remove.")
        else:
            print(f"No copies of {title} found in the library.")

    def checkout_book(self, title):
        """
        Checks out a book if it is available.

        :param title: The title of the book to checkout.
        """
        if title in self.books:
            if self.books[title]["available"] > 0:
                self.books[title]["available"] -= 1
                self.available_books -= 1
            else:
                print(f"No available copies of {title} to checkout.")
        else:
            print(f"Book {title} not found in the library.")

    def return_book(self, title):
        """
        Returns a book to the library.

        :param title: The title of the book to return.
        """
        if title in self.books:
            self.books[title]["available"] += 1
            self.available_books += 1
        else:
            print(f"Book {title} not found in the library. Cannot return.")

