def evaluate_security_feature(results):
    """
    Evaluates the security features based on the provided results dictionary.

    Parameters:
    results (dict): A dictionary containing keys in the format 'feature_name_support' and 'feature_name_validity'.

    Returns:
    dict: A dictionary where each key is a feature name and its value is a tuple containing the evaluation result dictionary and the score.
    """
    evaluation_results = {}

    for key in results.keys():
        if key.endswith('_support'):
            feature_name = key[:-8]
            support_key = feature_name + '_support'
            validity_key = feature_name + '_validity'

            if support_key in results and validity_key in results:
                is_supported = results[support_key]
                is_valid = results[validity_key]

                if is_supported and is_valid:
                    evaluation_dict = {feature_name: 'Supported and Valid'}
                    score = 100
                else:
                    evaluation_dict = {feature_name: 'Not Supported or Not Valid'}
                    score = 0

                evaluation_results[feature_name] = (evaluation_dict, score)

    return evaluation_results
