def set_logging_preferences(all_logs=False, version=1, **kwargs):
    """
    Sets the logging preferences for a given system version.

    Parameters:
    - all_logs (bool): If True, enables all logs for the specified version.
    - version (int): The system version for which to set logging preferences.
    - **kwargs: Specific logging preferences for individual log types.

    Returns:
    - dict: A dictionary with log types as keys and their preferences as values.

    Raises:
    - ValueError: If an unsupported log type is provided for the specified version.
    """
    log_types_by_version = {
        1: ['alert_event_logs', 'alert_logs', 'audit_logs', 'firewall_logs', 'ips_logs', 'ips_recording_logs', 'layer2_firewall_logs', 'third_party_logs'],
        2: ['alert_event_logs', 'alert_logs', 'audit_logs', 'firewall_logs', 'layer2_firewall_logs', 'third_party_logs', 'system_performance_logs', 'network_traffic_logs'],
        3: ['alert_logs', 'audit_logs', 'firewall_logs', 'network_traffic_logs', 'user_activity_logs', 'system_health_logs']
    }

    if version not in log_types_by_version:
        raise ValueError(f"Unsupported version: {version}")

    log_types = log_types_by_version[version]
    logging_preferences = {log_type: False for log_type in log_types}

    if all_logs:
        logging_preferences = {log_type: True for log_type in log_types}
    else:
        for log_type, preference in kwargs.items():
            if log_type in logging_preferences:
                logging_preferences[log_type] = preference
            else:
                raise ValueError(f"Log type {log_type} is not supported in version {version}")

    return logging_preferences
