import threading

# Lock for thread-safe operations
lock = threading.Lock()

def safe_calculation(a, b, operation):
    """
    Perform a thread-safe arithmetic operation on two numbers.

    Parameters:
    a (int): The first number.
    b (int): The second number.
    operation (str): The arithmetic operation to perform ('add', 'subtract', 'multiply', 'divide').

    Returns:
    int/float/str: The result of the operation or an error message.
    """
    try:
        with lock:
            if operation == 'add':
                return a + b
            elif operation == 'subtract':
                return a - b
            elif operation == 'multiply':
                return a * b
            elif operation == 'divide':
                if b == 0:
                    raise ValueError("Cannot divide by zero")
                return a / b
            else:
                raise ValueError("Unsupported operation")
    except Exception as e:
        return str(e)
