import threading

def read_scores_from_file(file_paths):
    """
    Reads student scores from multiple files concurrently and aggregates the scores for each student.

    Args:
    file_paths (list of str): A list of file paths containing student scores.

    Returns:
    dict: A dictionary with student names as keys and their total scores as values.
    """
    student_scores = {}
    lock = threading.Lock()

    def process_file(file_path):
        with open(file_path, 'r') as file:
            for line in file:
                line = line.strip()
                if line:
                    try:
                        name, score_str = line.split(',')
                        name = name.strip()
                        score_str = score_str.strip()
                        score = float(score_str)
                        if name:
                            with lock:
                                if name in student_scores:
                                    student_scores[name] += score
                                else:
                                    student_scores[name] = score
                    except (ValueError, IndexError):
                        continue

    threads = []
    for file_path in file_paths:
        thread = threading.Thread(target=process_file, args=(file_path,))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return student_scores
