def find_max_min(numbers):
    """
    Returns a tuple containing the maximum and minimum values from the list.
    If the list is empty, returns (None, None).

    :param numbers: List of integers
    :return: Tuple (max_value, min_value)
    """
    if not numbers:
        return (None, None)

    max_val = min_val = numbers[0]

    for num in numbers[1:]:
        if num > max_val:
            max_val = num
        elif num < min_val:
            min_val = num

    return (max_val, min_val)

# Example usage:
numbers = [3, 5, 1, 8, -2, 7, 10]
print(find_max_min(numbers))  # Output: (10, -2)
